--region public

function NightCatBossAllPlayerRankCell:FillPercentageRank(num)
    self.rankDojo = self._nightCatBossComponent:GetRankDojo()

    CfUtils.SetActive(self.RankNode, checkNumber(self.rankDojo.playerRank.hurt) ~= 0)

    num = checkNumber(num)
    local ImgRank = self.RankNode.transform:Find("ImgRank")
    local Txtranking = self.RankNode.transform:Find("Txtranking")
    local NotEnterNode = self.RankNode.transform:Find("NotEnterNode")

    -- 排名在1-100名
    local status = checkNumber(self.rankDojo.playerRank.ranking) > 4 and 5 or checkNumber(self.rankDojo.playerRank.ranking)
    --CfUtils.SetUISwitchImage(self.RankNode.transform:Find("ImgRank"), status)
    CfUtils.SetUISwitchText(Txtranking, status)
    CfUtils.SetUISwitchImage(ImgRank, status)
    CfUtils.FillText(self.Txtranking, self:RankingText(self.rankDojo.playerRank.ranking))
    CfUtils.SetActive(ImgRank, num == 0)

    CfUtils.SetActive(Txtranking, checkNumber(self.rankDojo.playerRank.hurt) > 0)
    CfUtils.SetActive(NotEnterNode, checkNumber(self.rankDojo.playerRank.hurt) == 0)
end

function NightCatBossAllPlayerRankCell:Refresh(data, isMe, index)
    if not data then
        return
    end
    self._data = data
    self._isMe = isMe

    if self._isMe then
        self:FillMeInfo()
    else
        self:FillOtherInfo()
    end
    CfUtils.SetActive(self.ImgMyself, self._isMe)
    local isEven = index % 2 == 0
    CfUtils.SetActive(self.Imgbg1, isEven)
    CfUtils.SetActive(self.Imgbg2, not isEven)
    CfUtils.SetActive(self.BtnDetails, isNotNull(data.team))
end
--endregion public

