    GameUtils.ShowCommonTeamsTipsBoard(self.BtnDetails, self._data.team, nil, nil, self._data.name)
end

function NightCatBossAllPlayerRankCell:RankingText(rankNum)
    rankNum = checkNumber(rankNum)
    -- 榜单上显示的范围
    local inRangeJudge = false
    local ranksInfo = CfUtils.GetCf(AutoIds.IdSetting6101, "NightCatBossRankRewardVo", true)
    for i = 1, #ranksInfo do
        ---@type NightCatBossRankRewardVo
        local rankInfo = ranksInfo[i]
        local upperLimit = rankInfo.upperLimit
        local lowerLimit = rankInfo.lowerLimit
        if not inRangeJudge then
            if rankNum >= upperLimit and rankNum <= lowerLimit then
                return rankNum
            end
            inRangeJudge = true
        end
        if rankNum >= upperLimit and rankNum <= lowerLimit then
            return rankInfo.name
        end
    end
end

